/* padding: верх право низ лево */
padding: 10px 20px 10px 20px;

/* padding: верх/низ право/лево */
padding: 10px 20px;

/* padding: все стороны одинаковые */
padding: 15px;

.box {
  width: 200px;
  height: 100px;
  padding: 20px;
  border: 3px solid #333;
  margin: 30px;
}

.box {
  width: 300px;
  padding: 20px;
  border: 5px solid #333;
}
/* Итоговая ширина: 300 + 20 + 20 + 5 + 5 = 350px! */

.box {
  box-sizing: border-box;
  width: 300px;
  padding: 20px;
  border: 5px solid #333;
}
/* Итоговая ширина: ровно 300px! */

.card {
  box-sizing: border-box;
  width: 300px;
  padding: 24px;
  border: 2px solid #ddd;
  margin: 16px;
  background-color: #fff;
}
